"""Writes low_stock.md: every item whose quantity is below its reorder level."""
import json
import os

os.makedirs("OCADE output", exist_ok=True)
items = json.load(open("stock.json"))

word_map = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10}

low = []
for i in items:
    qty = i['quantity']
    if isinstance(qty, str):
        qty = word_map.get(qty.lower(), 0)
    else:
        qty = int(qty)
    reorder = int(i['reorder_at'])
    if qty < reorder:
        low.append([i['sku'], i['name'], qty, reorder])

def make_table(rows, headers):
    col_widths = [len(h) for h in headers]
    for row in rows:
        for idx, val in enumerate(row):
            col_widths[idx] = max(col_widths[idx], len(str(val)))
    header_line = '| ' + ' | '.join(str(h).ljust(col_widths[idx]) for idx, h in enumerate(headers)) + ' |'
    sep_line = '| ' + ' | '.join('-' * col_widths[idx] for idx in range(len(headers))) + ' |'
    body_lines = []
    for row in rows:
        body_lines.append('| ' + ' | '.join(str(val).ljust(col_widths[idx]) for idx, val in enumerate(row)) + ' |')
    return '\n'.join([header_line, sep_line] + body_lines)

table_str = make_table(low, ['SKU', 'Name', 'Qty', 'Reorder at'])
with open('OCADE output/low_stock.md', 'w', encoding='utf-8') as out:
    out.write('# Items to reorder\n\n' + table_str + '\n')
print(f'{len(low)} items to reorder')
